"""Client for the NOAA CO-OPS datagetter API."""
import time

import httpx

from tidewater.models import Reading

DEFAULT_BACKOFF = (0.1, 0.2, 0.4)


class NoaaError(Exception):
    pass


def _get(client, params, backoff=DEFAULT_BACKOFF):
    for attempt, delay in enumerate((0.0,) + tuple(backoff)):
        if delay:
            time.sleep(delay)
        resp = client.get("", params=params)
        if resp.status_code < 500 and resp.status_code != 429:
            resp.raise_for_status()
            return resp.json()
    raise NoaaError(f"gave up after {attempt + 1} attempts")


def parse(station_id, payload):
    out = []
    sensor = payload.get("metadata", {}).get("sensor_serial")
    for row in payload.get("data", []):
        # API returns metres as a string, e.g. "1.234"
        level_mm = round(float(row["v"]) * 1000)
        out.append(
            Reading(
                station_id=station_id,
                observed_at=int(row["t_epoch"]),
                level_mm=level_mm,
                source="noaa",
                sensor_serial=sensor,
            )
        )
    return out


def fetch_range(station_id, cfg, begin=None, end=None):
    with httpx.Client(base_url=cfg["ingest"]["noaa_base_url"], timeout=30) as client:
        params = {
            "station": station_id,
            "product": "water_level",
            "datum": "MLLW",
            "units": "metric",
            "time_zone": "gmt",
            "format": "json",
        }
        if begin:
            params["begin_date"] = begin
        if end:
            params["end_date"] = end
        return parse(station_id, _get(client, params))

import time

import httpx
import respx

from tidewater.ingest import noaa


@respx.mock(base_url="https://example.test")
def test_parse_converts_to_mm(respx_mock):
    payload = {"data": [{"t_epoch": "1700000000", "v": "1.234"}]}
    out = noaa.parse("8443970", payload)
    assert out[0].level_mm == 1234
    assert out[0].sensor_serial is None


def test_parse_reads_sensor_serial():
    payload = {"metadata": {"sensor_serial": "A1-0042"}, "data": [{"t_epoch": "1700000000", "v": "0.5"}]}
    assert noaa.parse("8443970", payload)[0].sensor_serial == "A1-0042"


@respx.mock(base_url="https://example.test")
def test_retry_backoff_is_bounded(respx_mock):
    route = respx_mock.get("").mock(
        side_effect=[httpx.Response(503), httpx.Response(503), httpx.Response(200, json={})]
    )
    start = time.monotonic()
    with httpx.Client(base_url="https://example.test") as client:
        noaa._get(client, {})
    elapsed = time.monotonic() - start
    assert route.call_count == 3
    assert elapsed < 0.35

